package admin

const connectionTemplate = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MCP Gateway · Connection</title><style>` + connectionCSS + `</style><script src="{{.BasePath}}/admin/connection.js" defer></script>{{if .Permission}}<script src="{{.BasePath}}/admin/permissions.js" defer></script>{{end}}</head><body><header class="top"><a class="brand" href="{{.BasePath}}/admin/servers">MCP Gateway</a><nav aria-label="Administration"><a href="{{.BasePath}}/admin/servers">Servers</a><a href="{{.BasePath}}/admin/connection" aria-current="page">Connection</a></nav><div class="sign-out"><form method="post" action="{{.BasePath}}/admin/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="secondary">Sign out</button></form></div></header><main class="connection-page client-workspace" data-connection data-client-workspace="true" data-base="{{.BasePath}}" data-client="{{if .Selected}}{{.Selected.ID}}{{end}}">
<section class="connection-panel setup-panel"><div class="setup-address"><h1>Connection</h1>{{if .Endpoint}}<div class="copy-row"><input id="mcp-endpoint" readonly value="{{.Endpoint}}" aria-label="MCP endpoint"><button type="button" class="secondary" data-copy="mcp-endpoint">Copy address</button></div>{{else}}<p>Connection address is not configured. Set GATEWAY_MCP_EXTERNAL_URL to the external MCP endpoint.</p>{{end}}</div><div class="setup-guides">{{if .Endpoint}}<details><summary>Connect Codex</summary><pre id="codex-command">{{.Command}}</pre><button type="button" class="secondary" data-copy="codex-command">Copy command</button><p>Set MCP_GATEWAY_TOKEN in the environment of the Codex process to the key you created. The command reads this variable; it does not contain the key. For the desktop app, the variable must be available to the app process; setting it only in a different terminal does not configure the running app. Reload the MCP connection after configuring it.</p></details>{{end}}
{{if .Endpoint}}<details><summary>Connect Claude Code</summary><p>Create a separate key named Claude Code. Set MCP_GATEWAY_TOKEN in the environment of the terminal that starts Claude Code. Merge one configuration below into your project's .mcp.json, preserving existing servers. The variable reference stays in the file; the key does not.</p><h3>Bearer</h3><pre id="claude-bearer">{{.ClaudeBearer}}</pre><button type="button" class="secondary" data-copy="claude-bearer">Copy Bearer configuration</button><details><summary>Use X-API-Key instead</summary><pre id="claude-api-key">{{.ClaudeAPIKey}}</pre><button type="button" class="secondary" data-copy="claude-api-key">Copy X-API-Key configuration</button></details><p>Choose one configuration. Start Claude Code in that project, approve the MCP configuration when prompted, then use /mcp to check the connection. After changing the environment or configuration, start a new session. These instructions are for Claude Code.</p></details>{{end}}
<details><summary>Authentication headers</summary><p>Use the same key with either authentication header:</p><pre>Authorization: Bearer &lt;key&gt;
or
X-API-Key: &lt;key&gt;</pre><p>Choose one header per request. Sending both or repeating a header is rejected. Codex uses Bearer by default. Use a separate key for each client.</p><p>Access depends on each principal policy and exact tool permissions, bounded by global switches. New keys have no tool access. Administrator sign-in is separate.</p></details>
</div></section><div class="client-layout"><aside class="client-rail"><h2>Clients <small>/ <span data-key-count>{{len .Keys}}</span></small></h2><label class="sr" for="client-search">Search clients</label><input id="client-search" type="search" placeholder="Search clients…"><div data-key-list>{{$root:=.}}{{range .Keys}}<a class="client-link{{if and $root.Selected (eq $root.Selected.ID .ID)}} active{{end}}" data-client-link data-key-id="{{.ID}}" data-client-search="{{.Name}} {{.ID}}" href="{{$root.BasePath}}/admin/connection/permissions/{{.ID}}"><b>{{.Name}}</b><small data-client-access>{{if not .Managed}}Managed by environment · {{end}}{{if .Legacy}}Shared access{{else}}{{.Configured}} configured{{end}} · {{.Effective}} available</small></a>{{end}}</div><details id="new-client" {{if not .Selected}}open{{end}}><summary>New client</summary><form class="create-key-form" data-key-create method="post" action="{{.BasePath}}/admin/connection/keys/create"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><label>Key name<input name="name" required maxlength="128" placeholder="Laptop or Personal Assistant" autocomplete="off"></label><button class="primary">Create key</button></form></details></aside><div class="client-content"><div class="key-card one-time" data-issued {{if not .Token}}hidden{{end}}><h3>Client key</h3><p>The value is hidden after 60 seconds or when you leave this page.</p><div class="copy-row"><input id="issued-key" readonly value="{{.Token}}" autocomplete="off" spellcheck="false" aria-label="Client key"><button type="button" class="secondary" data-copy="issued-key">Copy key</button></div><button type="button" class="secondary" data-dismiss>Hide key</button><noscript><p>JavaScript is disabled; automatic hiding is unavailable. Select and copy the value manually, then open <a href="{{.BasePath}}/admin/connection">Connection</a> to close this response.</p></noscript></div>
<p data-key-status role="status" aria-live="polite"></p><button type="button" class="secondary" data-keys-refresh hidden>Refresh keys</button>
{{if .Selected}}{{$k:=.Selected}}<header class="client-heading"><div><a class="back-clients" href="{{.BasePath}}/admin/connection">← Clients</a><h1>{{$k.Name}}</h1><p><span class="policy-tag" data-selected-policy>{{if $k.Legacy}}Shared access{{else}}Restricted{{end}}</span> <span data-selected-access>{{$k.Configured}} configured · {{$k.Effective}} available</span></p></div><details class="client-settings"><summary>Client settings</summary><p data-key-lock-note hidden>Save or reload the permission draft before showing or changing this key.</p><p>Principal <code>{{$k.ID}}</code></p>{{if $k.Managed}}<p><code>{{$k.Prefix}}…</code> · Created {{$k.CreatedAt}}</p>{{if $k.Recoverable}}<form data-key-reveal method="post" action="{{.BasePath}}/admin/connection/keys/{{$k.ID}}/reveal"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><div class="key-buttons"><button type="submit" class="secondary" data-reveal-id="{{$k.ID}}">Show key</button><button type="button" class="secondary" data-copy-key="{{$k.ID}}">Copy key</button></div></form>{{else}}<p>Repeat display is unavailable. Create a new key if you need to show it again.</p>{{end}}<details><summary>Delete key</summary><form data-key-delete method="post" action="{{.BasePath}}/admin/connection/keys/{{$k.ID}}/delete"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><label>Type {{$k.Name}} to confirm deletion<input name="confirm" required autocomplete="off" maxlength="128"></label><p>Clients using this key will lose access. This cannot be undone.</p><button class="danger">Delete key</button></form></details>{{else}}<p>Managed by environment. Preserved for existing clients; the value is not displayed here.</p>{{end}}</details></header>{{if .Permission}}{{template "permissions" .Permission}}{{end}}{{else}}<div class="client-empty"><h1>Clients</h1><p>Choose a client to manage its key and MCP permissions, or create a new one.</p><p>New clients start with no tool access. Server and tool switches remain the upper limit.</p></div>{{end}}</div></div><p class="page-foot">{{if .Authentik}}Signed in as {{.User}} · {{end}}Registry revision <span data-key-revision>{{.Revision}}</span>. Audit · <span data-audit-status>{{.Audit}}</span></p><noscript><p>Forms work without JavaScript. Copy buttons require JavaScript; select the text manually.</p></noscript></main></body></html>`
